MOD = 998244353

@lru_cache(None)
def dp(x, y, N, last):
    if x == 0 and y == 0:
        return 0
    if N == 0 and x != 0 or N == 1 and y != 0:
        return 0
    if N == 1 and x != 1:
        return 0

    if last == N:
        return comb(N, N - 1) % MOD
    if last < N:
        xyz = 1 if last == N - 2 else y
    elif last == N - 1:
        xyz = 1 if x == 0 else comb(x, x - 1) % MOD
    else:
        xyz = 1 if y == 0 else comb(y, y - 1) % MOD

    return (comb(x, x - 1) * comb(y, y - 1) * dp(x + 1, y, N - 1, last + 1) +\
            1 * comb(x, x - 1) * comb(y, y - 1) * dp(x - 1, y, N - 1, last - 1) -\
            xyz * dp(x, y, N - 1, last) + MOD) % MOD

