def generate_frequencies(p, n):
    total_days = n
    available_frequencies = list(range(1, 25))
    assigned_frequencies = [0] * total_days

    def backtrack(day=0):
        if day == total_days:
            return True
        for i in range(day, total_days):
            if all(assigned_frequencies[i] > assigned_frequencies[j] for j in range(i)):
                assigned_frequencies[i] = available_frequencies[day]
                if backtrack(i + 1):
                    return True
                assigned_frequencies[i] = 0
        return False

    optimal_day = None
    optimal_count = float('inf')
    for perm in permutations(range(1, n + 1)):
        if all(perm[i - 1] < perm[i] for i in range(1, len(perm))):
            if backtrack(0):
                current_count = sum(1 for assigned, actual in zip(assigned_frequencies, perm) if assigned == actual)
                if current_count < optimal_count:
                    optimal_count = current_count
                    optimal_day = day

    return [assigned_frequencies[i] for i in range(total_days) if i != optimal_day]

