def mod_inverse(a, mod):
    b = mod
    x0, x1 = 1, 0
    y0, y1 = 0, 1
    while a > 1:
        q = a // b
        t = a % b
        a, b = b, t
        xi, x2xi = x1, x1 - q * x0
        yi, y2yi = y1, y1 - q * y0
        x0, x1 = xi, x2xi
        y0, y1 = yi, y2yi
    return x1 % mod

def solve(N, A):
    mod = 998244353
    invmod = mod_inverse(N-1, mod)
    C = [[0] * (N-1) for _ in range(N)]
    for i in range(N):
        C[i][i] = 1
    for j in range(1, N):
        for i in range(N-j):
            C[i][i+j] = (C[i+1][i+j] + (binomial(N-2-j, i+1) * C[i+1][i] % mod)) % mod
    res = 0
    for i in range(N):
        res += C[0][i] * binomial(N-1, N-1-i) % mod * invmod % mod * A[i] % mod
        res %= mod
    return res

def binomial(n, k):
    if k < 0 or k > n:
        return 0
    res = 1
    for i in range(k):
        res = (res * (n - i) // (i + 1)) % 998244353
    return res

