            edge_connectivities[start_layout[u]].append((start_layout[v], u))
            tasks[u] |= {v}

    # Convert tasks to non-decreasing orders
    tasks_order = []
    while tasks:
        lowest = min(tasks.keys())
        tasks_order.extend(tasks.pop(lowest))

    # Divide order into 3-way partitions
    first_partitions = []
    mid_partitions = []
    for u in tasks_order:
        if first_partitions and u < first_partitions[-1][-1]:
            mid_partitions.append(first_partitions.pop())
        first_partitions.append((u, u))
        if mid_partitions:
            mid_partitions[-1][-1] = max(u, mid_partitions[-1][-1])

    # Fill edge connectivities between partitions
    for u in tasks_order:
        for v in first_partitions:
            if u < v[0]:
                first_partitions.remove(v)
                edge_connectivities[u].append((v[1], v[0]))
                break
        else:
            for v in mid_partitions:
                if u < v[0]:
                    mid_partitions.remove(v)
                    edge_connectivities[u].append((v[1], v[0]))
                    break
            else:
                for v in reversed(mid_partitions):
                    if u < v[0]:
                        mid_partitions.remove(v)
                        edge_connectivities[u].append((v[1], v[0]))
                        break

    return edge_connectivities

