import sys

def floyd_warshall(graph):
    n = len(graph)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                graph[i][j] = min(graph[i][j], graph[i][k] + graph[k][j])

    return graph

def longest_path(graph, source, days):
    n = len(graph)
    dp = [[float('inf')] * n for _ in range(days + 1)]
    for edge in graph[source]:
        dp[-1][edge[0]] = edge[1]
        dp[-1][edge[1]] = edge[1]

