            permutation_count[(j, i)] += 1
        for i in range(len(A) + 1):
            permutation_count[(A[i], A[(i+1)%len(A)])] += N - i

    dp = [0] * 64 
    dp[0] = 1
    mod = 998244353

    for p in range(5):
        next_dp = [0] * 64 
        for d in range(64):
            if d >> p & 1:
                for next_value in range(64):
                    if d or (next_value >> ((p+1)%5) & 1):
                        next_dp[next_value] = (next_dp[next_value] + dp[d ^ (1 << next_value)]) % mod
