from operator import mul
from collections import defaultdict

MOD = 998244353

def lcm(x, y):
    return x * y // gcd(x, y)

def reduce_lcm(numbers):
    return reduce(lcm, numbers)

def factorize(n):
    factors = defaultdict(int)
    d = 2
    while n > 1:
        while n % d == 0:
            factors[d] += 1
            n //= d
        d += 1
    return factors

def solve(n, nums):
    if n == 1:
        return 1
    cur = 0
    for i in range(1, n):
        cur = (cur * 2) % MOD
    t = n - 1
    b = factorize(nums[0])
    slash = prod = 1
    for k, v in b.items():
        slash *= (v + 1)
    for i in range(2, n + 1):
        ew = prod
        prod = prod * reduce_lcm(nums[i - 1]) % MOD
        prod %= MOD
        el = prod * prod * t * (t - 1) % MOD // (ew * t * t) % MOD
        t -= 2
    return (cur * reduce(mul, prod, 1) * slash) % MOD

