def maxPathCount(n, m, transitions):
    # Build graph
    graph = defaultdict(list)
    for u, v, a, b in transitions:
        graph[u-1].append((v-1, a, b))
        graph[v-1].append((u-1, a, b))

    # Bellman-Ford to find shortest paths
    dist = [float('inf')] * n
    dist[0] = 0  # Starting path to house 0 (berdeltaeitsynamo)
    for _ in range(n):
        for i in range(n):
            for nei, weight, _ in graph[i]:
                if dist[nei] > dist[i] + weight:
                    dist[nei] = dist[i] + weight

    # Floyd-Warshall for stockcrosspaths
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i] != float('inf') and dist[j] != float('inf') and dist[i] + dist[j] > dist[i+j]:
                    dist[i+j] = min(dist[i] + dist[j], dist[i+j])

    # Prepare output
    output = []
    for t in range(m):
        max_dist = float('-inf')
        for i in range(n):
            for j in range(i+1, n):
                if dist[i] != float('inf') and dist[j] != float('inf'):
                    max_dist = max(max_dist, dist[i]+dist[j]+t*10)
        output.append(max_dist)
