        node = node[1]
    children = {
        'l': left_children[node],
        'r': right_children[node]
    }
    result = {left_children[node][0][0], right_children[node][0][0]}
    for child, (parent_left, parent_right) in children.items():
        if parent_left is not None and parent_left != node:
            result = result.union(find_union(parent_left))
        if parent_right is not None and parent_right != node:
            result = result.union(find_union(parent_right))
