from collections import defaultdict

def find(parent, node):
    if parent[node] != node:
        parent[node] = find(parent, parent[node])
    return parent[node]

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        if rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        elif rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def solve(n, m, connections):
    parent = list(range(n))
    rank = [0] * n

    for i in range(m):
        flight = list(map(int, input().split()))
        union(parent, rank, connections[flight[0]-1], connections[flight[1]-1])

    result = []
    for i in range(n):
        for j in range(i+1, n):
            if find(parent, i) != find(parent, j):
                result.append(f"{i+1} {j+1} 1")
            else:
                result.append(f"{i+1} {j+1} 0")

    return result

