from math import gcd
from functools import reduce
from operator import mul

def lcm(a, b):
    return a * b // gcd(a, b)

def extended_gcd(a, b):
    if b == 0:
        return a, 1, 0
    else:
        g, x, y = extended_gcd(b, a % b)
        return g, y, x - (a // b) * y

def get_coefficients(n, primes):
    mod = 10**9 + 7
    factors = [reduce(lcm, [p**(i + 1) - i - 1 for i in range(n - 1)]) for p in primes]
    factors = [a if a > 0 else -a for a in factors]
    coefficients = set()
    for i in range(n - 1):
        for j in range(i):
            a, _, _ = extended_gcd(factors[i], factors[j])
            if a > 0:
                coefficients.add(-a * mod)
    coefficients = list(coefficients)
    coefficients.sort()
    for i in range(len(coefficients) - 1):
        coefficients[i] = coefficients[i] % mod
    for i in range(1, n + 1):
        coefficients.append(coefficients[-2])
    return coefficients

def solve(n, primes):
    coefficients = get_coefficients(n, primes)
    degree = n
    polynomial = sum(coefficients[i] * (x**i) for i in range(n + 1))
    return degree, coefficients

